Cached `GetType()` once and replaced the per-byte loop with size-specialized unrolled byte assembly, which compiles to single loads for the common 1/2/4/8-byte types and removes loop overhead.

```cpp
template <typename T>
T FieldBase::GetValue(const FIT_UINT8 fieldArrayIndex) const
{
    const FIT_UINT8 baseType = GetType() & FIT_BASE_TYPE_NUM_MASK;
    const FIT_UINT8 size = baseTypeSizes[baseType];
    if (fieldArrayIndex >= (FIT_UINT8)values.size())
    {
        return *reinterpret_cast<const T*>(baseTypeInvalids[baseType]);
    }

    const FIT_UINT8* p = &values[fieldArrayIndex * size];
    T rv = 0;
    if (size == 1)
    {
        rv = static_cast<T>(p[0]);
    }
    else if (size == 2)
    {
        rv = static_cast<T>(p[0]) | (static_cast<T>(p[1]) << 8);
    }
    else if (size == 4)
    {
        rv = static_cast<T>(p[0]) | (static_cast<T>(p[1]) << 8) |
             (static_cast<T>(p[2]) << 16) | (static_cast<T>(p[3]) << 24);
    }
    else if (size == 8)
    {
        rv = static_cast<T>(p[0]) | (static_cast<T>(p[1]) << 8) |
             (static_cast<T>(p[2]) << 16) | (static_cast<T>(p[3]) << 24) |
             (static_cast<T>(p[4]) << 32) | (static_cast<T>(p[5]) << 40) |
             (static_cast<T>(p[6]) << 48) | (static_cast<T>(p[7]) << 56);
    }
    else
    {
        for (int i = 0; i < size; i++)
        {
            rv |= static_cast<T>(p[i]) << (i * 8);
        }
    }
    return rv;
}
```

